// Wat dit oplevert en waarom het zo weinig is.
//
// De vorige versie haalde per product een vaste tarievenpagina op en liet Claude
// die lezen. Dat is op 2026-08-16/17 gemeten en het werkte niet: Amex' URL gaf
// 404, ABN's pagina bleek marketingtekst, ABN's tarievenpagina een lege
// JS-schil, Revolut en Trading 212 antwoorden 403 achter Cloudflare, ING
// verbreekt de verbinding, en Knabs pagina met meerdere producten leverde de
// CREDITCARD (2%) terwijl om de betaalpas was gevraagd — die 1,4% kost. Eén
// verkeerd getal is erger dan geen getal, want een verkeerd getal wordt gebruikt.
//
// LaVega's eigen /api/agent/travel-facts doet het wel goed, en die code draagt
// twee dingen die tijd hebben gekost om te leren: tool_choice moet AUTO zijn
// (geforceerd antwoordt het model vóór het één keer heeft gezocht, gemeten: nul
// zoekopdrachten, lege velden), en het antwoord wordt vastgepind op het product
// waarnaar gevraagd is. Dat hier namaken betekent die twee lessen kopiëren en
// daarna uit elkaar laten groeien.
//
// Dus doet deze workflow nog maar één ding: hij TIKT het endpoint aan. Dat
// antwoordt meteen met wat bekend is en zoekt de gaten op de achtergrond op. Eén
// keer per dag betekent: als iemand het reisblok opent, staat het antwoord er al.
// Dat haalt de enige echte zwakte van de agent weg — de wachttijd — zonder aan
// zijn nauwkeurigheid te komen.

// Welke producten warm gehouden worden. Publieke productnamen, verder niets:
// er gaat geen enkel gegeven over de rekeningen van de eigenaar doorheen.
//
// De namen MOETEN overeenkomen met wat productOf() in packages/core/src/travel.ts
// oplevert — bank + "betaalpas" of "creditcard" — anders komt het antwoord onder
// een sleutel te staan die LaVega nooit opvraagt.
const PRODUCTS = [
  'ING betaalpas', 'ING creditcard',
  'ABN AMRO betaalpas', 'ABN AMRO creditcard',
  'Rabobank betaalpas', 'Rabobank creditcard',
  'Knab betaalpas', 'bunq betaalpas',
  'Revolut betaalpas', 'Wise betaalpas',
  'Trading 212 betaalpas', 'American Express creditcard',
];

// Bestemmingen waarvoor de voorwaarden vooraf worden opgehaald. Tarieven
// verschillen per markt, dus de cache is per valuta.
return [
  { json: { homeCountry: 'NL', destination: 'US', currency: 'USD', providers: PRODUCTS, knownFacts: [] } },
  { json: { homeCountry: 'NL', destination: 'GB', currency: 'GBP', providers: PRODUCTS, knownFacts: [] } },
];
